<div class="page-heading"><div><h1>Usuarios y configuración</h1><p>Administrar accesos y reglas operativas</p></div></div><div class="row g-4"><div class="col-lg-5"><form class="panel mb-4" method="post" action="<?=url('index.php?page=usuario-save')?>"><?=csrf_field()?><h2 class="h5 mb-3">Nuevo usuario</h2><label class="form-label">Nombres</label><input class="form-control mb-3" name="nombres" required minlength="3"><label class="form-label">Usuario</label><input class="form-control mb-3" name="usuario" required pattern="[A-Za-z0-9_.-]{4,30}"><label class="form-label">Contraseña</label><input type="password" class="form-control mb-3" name="clave" required minlength="10"><label class="form-label">Rol</label><select class="form-select mb-3" name="rol_id"><option value="2">Vendedor</option><option value="1">Administrador</option></select><button class="btn btn-primary w-100">Crear usuario</button></form><form class="panel" method="post" action="<?=url('index.php?page=config-save')?>"><?=csrf_field()?><h2 class="h5 mb-3">Alertas de vencimiento</h2><label class="form-label">Días de anticipación</label><input type="number" min="1" max="365" class="form-control mb-3" name="dias" value="<?=$dias?>" required><button class="btn btn-outline-primary w-100">Guardar configuración</button></form></div><div class="col-lg-7"><div class="panel"><h2 class="h5 mb-3">Usuarios registrados</h2><div class="table-responsive"><table class="table"><thead><tr><th>Nombre</th><th>Usuario</th><th>Rol</th><th>Último acceso</th><th>Estado</th></tr></thead><tbody><?php foreach($usuarios as$u):?><tr><td><?=e($u['nombres'])?></td><td><?=e($u['usuario'])?></td><td><?=e(ucfirst($u['rol']))?></td><td><?=$u['ultimo_acceso']?date('d/m/Y H:i',strtotime($u['ultimo_acceso'])):'—'?></td><td><span class="badge text-bg-<?=$u['activo']?'success':'secondary'?>"><?=$u['activo']?'Activo':'Inactivo'?></span></td></tr><?php endforeach?></tbody></table></div></div></div></div>
